var o=`1179-sopa-de-tortilla`;var t=`world-1179`;var a=`MX`;var n=`central-america-caribbean`;var s=4;var l=43;var r={en:`Sopa de Tortilla`,ua:`Тортилья-суп`};var d={en:`Sopa de Tortilla is a dish from Mexico prepared with yellow onion, garlic, tomato, dried guajillo chilies. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Тортилья-суп, страва кухні країни Мексика, яку готують із таких продуктів: жовта цибуля, часник, помідор, сушений перець гуахільйо. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var m=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`tomato`,360,`g`],[`canola-oil`,35,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 20 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 20 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:20,i:[[`chicken-stock`,1150,`ml`],[`dried-guajillo-chilies`,3,`pcs`],[`ground-cumin`,4,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 9 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 9 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:9,i:[[`corn-tortillas`,8,`pcs`],[`canola-oil`,150,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`avocado`,2,`pcs`],[`queso-fresco`,120,`g`],[`cilantro`,25,`g`]]}];var u={slug:o,id:t,country:`MX`,region:n,servings:4,minutes:43,title:r,text:d,steps:m};export{a as country,u as default,t as id,l as minutes,n as region,s as servings,o as slug,m as steps,d as text,r as title};